    @PostMapping("/inventory/search")
    public AiInventoryResult searchInventory(
        @RequestHeader(AiErpInternalHeaders.INTERNAL_TOKEN) String token,
        @RequestHeader(AiErpInternalHeaders.TENANT_ID) Long tenantId,
        @RequestHeader(AiErpInternalHeaders.USER_ID) Long userId,
        @RequestBody AiInventoryQuery request
    ) {
        return call(token, tenantId, userId, () -> documentService.searchProductInventory(request));
    }

    @PostMapping("/inventory/changes/search")
    public AiInventoryResult searchInventoryChanges(
        @RequestHeader(AiErpInternalHeaders.INTERNAL_TOKEN) String token,
        @RequestHeader(AiErpInternalHeaders.TENANT_ID) Long tenantId,
        @RequestHeader(AiErpInternalHeaders.USER_ID) Long userId,
        @RequestParam("productSkuId") Long productSkuId,
        @RequestBody AiInventoryQuery request
    ) {
        return call(token, tenantId, userId,
            () -> documentService.searchProductInventoryChanges(productSkuId, request));
    }

    @PostMapping("/products/search")
    public AiErpToolResult searchProducts(
        @RequestHeader(AiErpInternalHeaders.INTERNAL_TOKEN) String token,
        @RequestHeader(AiErpInternalHeaders.TENANT_ID) Long tenantId,
        @RequestHeader(AiErpInternalHeaders.USER_ID) Long userId,
        @RequestBody AiErpSearchRequest request
    ) {
        return call(token, tenantId, userId, () -> documentService.searchProducts(request));
    }

    @PostMapping("/suppliers/search")
    public AiErpToolResult searchSuppliers(
        @RequestHeader(AiErpInternalHeaders.INTERNAL_TOKEN) String token,
