    public AiErpToolResult executeOutsource(
        @RequestHeader(AiErpInternalHeaders.INTERNAL_TOKEN) String token,
        @RequestHeader(AiErpInternalHeaders.TENANT_ID) Long tenantId,
        @RequestHeader(AiErpInternalHeaders.USER_ID) Long userId,
        @RequestParam("action") String action,
        @RequestBody AiErpOutsourceOrderForm form,
        HttpServletRequest request
    ) {
        return call(token, tenantId, userId,
            () -> documentService.executeOutsource(action, form, tenantId, request));
    }

    /**
     * 内部接口只信任共享 token；通过校验后再建立现有 ERP 服务依赖的用户和工厂上下文。
     */
    private <T> T call(String token, Long tenantId, Long userId, Callable<T> action) {
        String expected = aiProperties.getMcp() == null ? null : aiProperties.getMcp().getInternalToken();
        if (StringUtils.isBlank(expected) || !StringUtils.equals(expected, token)) {
            throw new ServiceException("AI ERP内部调用鉴权失败");
        }
        if (tenantId == null || userId == null) {
            throw new ServiceException("AI ERP内部调用缺少工厂或用户上下文");
        }

        AiRunContext context = new AiRunContext();
        context.setTenantId(tenantId);
        context.setSysUserId(userId);
        return loginContextRunner.run(context, () -> invoke(action));
    }

    /**
     * 将存量 ERP 的受检异常统一转换为接口错误，保留 ServiceException 的业务提示。
     */
    private <T> T invoke(Callable<T> action) {
        try {
            return action.call();
        } catch (ServiceException e) {
            throw e;
        } catch (Exception e) {
            throw new ServiceException(StringUtils.defaultIfBlank(e.getMessage(), "AI ERP单据处理失败"), e);
        }
    }
}
