private AiErpToolResult withLock(Long tenantId, String kind, String number,
                                 Callable<AiErpToolResult> operation) throws Exception {
    RLock lock = redissonClient.getLock("ai:erp:create:" + tenantId + ":" + kind + ":" + number);
    boolean acquired;
    try {
        acquired = lock.tryLock(5, 60, TimeUnit.SECONDS);
    } catch (InterruptedException e) {
        Thread.currentThread().interrupt();
        throw new ServiceException("等待单据创建锁时被中断", e);
    }
    if (!acquired) {
        throw new ServiceException("同一原始单号正在创建，请稍后重试");
    }
    try {
        return operation.call();
    } finally {
        if (lock.isHeldByCurrentThread()) {
            lock.unlock();
        }
    }
}

