        r.payload = null;
        return r;
    }
}
package com.allthinkstars.framework.iot.ai.tools;

import com.fasterxml.jackson.databind.ObjectMapper;

import java.lang.reflect.Array;
import java.util.Collection;

/**
 * 工具结果统一封装器
 * ToolRegistry 在方法调用完成后统一经由这里构建协议层结果，避免业务方法感知 ToolResult
 */
public final class ToolResults {

    private ToolResults() {
    }

    public static ToolResult success(ObjectMapper objectMapper, Object raw) {
        ToolResult result = new ToolResult();
        result.setOk(true);
        result.setPreview(buildPreview(raw));
        ToolPayload payload = ToolPayloadProjector.project(objectMapper, raw);
        result.setPayload(payload);
        return result;
    }

    public static ToolResult fail(String code, String message) {
        ToolResult result = new ToolResult();
        result.setOk(false);
        result.setCode(code);
        result.setMessage(message);
        result.setPreview(message == null ? "" : message);
        result.setPayload(null);
        return result;
    }

    private static String buildPreview(Object raw) {
        if (raw == null) {
            return "";
        }
        if (raw instanceof CharSequence) {
            return raw.toString();
        }
        if (raw instanceof Collection<?>) {
            return "工具调用成功，返回" + ((Collection<?>) raw).size() + "条结果";
        }
        if (raw.getClass().isArray()) {
            return "工具调用成功，返回" + Array.getLength(raw) + "条结果";
        }
        return "工具调用成功，已返回可供回答的业务结果。";
    }
}

