@Override
public void reportFurnaceAngleSensorFaultStatus(FurnaceAngleSensorFaultStatusReportDto dto, Long did) {
    var key = RedisKeyEnum.FURNACE_ANGLE_SENSOR_FAULT_STATUS.buildKeyThrowable(did, dto.getFn());
    RBucket<String> bucket = redissonClient.getBucket(key);

    FurnaceAngleSensorFaultStatusVo previous = Optional.ofNullable(bucket.get())
        .filter(StringUtils::hasText)
        .map(i -> SerializationUtils.fromStr(i, FurnaceAngleSensorFaultStatusVo.class))
        .orElse(null);

    var current = new FurnaceAngleSensorFaultStatusVo();
    current.setDid(did);
    current.setFurnaceCode(dto.getFurnaceCode());
    current.setFn(dto.getFn());
    current.setStatus(Boolean.TRUE.equals(dto.getFault()) ? "FAULT" : "NORMAL");
    current.setFault(dto.getFault());
    current.setFaultCode(dto.getFaultCode());
    current.setLastValidReadAt(dto.getLastValidReadAt());
    current.setStatusChangedAt(dto.getStatusChangedAt());

    bucket.set(SerializationUtils.toStr(current));

    var statusChanged = Objects.isNull(previous)
        || !Objects.equals(previous.getFault(), current.getFault())
        || !Objects.equals(previous.getFaultCode(), current.getFaultCode());
    if (statusChanged) {
        log.info("【角度传感器故障判断】did={} fn={} furnaceCode={} 状态[{}->{}] faultCode={} lastValidReadAt={} statusChangedAt={}",
            did, dto.getFn(), dto.getFurnaceCode(),
            Optional.ofNullable(previous).map(FurnaceAngleSensorFaultStatusVo::getStatus).orElse("UNKNOWN"),
            current.getStatus(), current.getFaultCode(), current.getLastValidReadAt(), current.getStatusChangedAt());
    }
}

@Override
public FurnaceAngleSensorFaultStatusVo getFurnaceAngleSensorFaultStatus(Long did, String furnaceCode) {
    var furnace = tbDeviceFurnaceMapper.selectOne(Wrappers.lambdaQuery(TbDeviceFurnace.class)
        .eq(TbDeviceFurnace::getDeviceInternalId, did)
        .eq(TbDeviceFurnace::getFnCode, furnaceCode));
    if (Objects.isNull(furnace)) {
        throw new ServiceException(String.format("目标炉体不存在, did = %s, furnaceCode = %s", did, furnaceCode));
    }

    var key = RedisKeyEnum.FURNACE_ANGLE_SENSOR_FAULT_STATUS.buildKeyThrowable(did, furnace.getFnNo());
    RBucket<String> bucket = redissonClient.getBucket(key);
    var status = Optional.ofNullable(bucket.get())
        .filter(StringUtils::hasText)
        .map(i -> SerializationUtils.fromStr(i, FurnaceAngleSensorFaultStatusVo.class))
        .orElseGet(FurnaceAngleSensorFaultStatusVo::new);

    status.setDid(did);
    status.setFurnaceCode(furnaceCode);
    status.setFn(furnace.getFnNo());
    if (Objects.isNull(status.getStatus())) {
        status.setStatus("UNKNOWN");
        status.setFault(null);
        status.setFaultCode(null);
    }
    return status;
}

